// ============================================================================
// Interrupt_Controller_apb: APB4 register wrapper around Interrupt_Controller_top (generated by
// scripts/apb/gen_apb.py from scripts/apb/specs/Interrupt_Controller.json; do not edit)
// ----------------------------------------------------------------------------
//  - APB4 slave, zero wait states (PREADY = PSEL & PENABLE), 32-bit data,
//    12-bit byte address; PSLVERR on an unmapped or misaligned access.
//  - PSTRB byte lanes apply to every writable register.
//  - The core runs on PCLK/PRESETN; protocol pins pass through unchanged.
//  - Register map: docs/ip/Interrupt_Controller.md
// ============================================================================
module Interrupt_Controller_apb #(
  parameter logic [3:0] AXI_ID = 4'd10
) (
  input  logic        PCLK,
  input  logic        PRESETN,
  input  logic        PSEL,
  input  logic        PENABLE,
  input  logic        PWRITE,
  input  logic [11:0] PADDR,
  input  logic [31:0] PWDATA,
  input  logic [3:0]  PSTRB,
  output logic [31:0] PRDATA,
  output logic        PREADY,
  output logic        PSLVERR,
  output logic        irq,
  input logic [31:0] irq_src,
  output logic cpu_irq,
  output logic [3:0] m_awid,
  output logic [31:0] m_awaddr,
  output logic [7:0] m_awlen,
  output logic [2:0] m_awsize,
  output logic [1:0] m_awburst,
  output logic [2:0] m_awprot,
  output logic m_awvalid,
  input logic m_awready,
  output logic [31:0] m_wdata,
  output logic [3:0] m_wstrb,
  output logic m_wlast,
  output logic m_wvalid,
  input logic m_wready,
  input logic [3:0] m_bid,
  input logic [1:0] m_bresp,
  input logic m_bvalid,
  output logic m_bready,
  output logic [3:0] m_arid,
  output logic [31:0] m_araddr,
  output logic [7:0] m_arlen,
  output logic [2:0] m_arsize,
  output logic [1:0] m_arburst,
  output logic [2:0] m_arprot,
  output logic m_arvalid,
  input logic m_arready,
  input logic [3:0] m_rid,
  input logic [31:0] m_rdata,
  input logic [1:0] m_rresp,
  input logic m_rlast,
  input logic m_rvalid,
  output logic m_rready
);
  localparam logic [31:0] ID_VALUE = 32'h5C0B0100;

  // ---------------- APB decode ----------------
  wire        acc     = PSEL & PENABLE;
  wire        wr      = acc & PWRITE;
  wire        rd      = acc & ~PWRITE;
  wire [31:0] wmask   = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [11:0] hit;
  always_comb begin
    hit = '0;
    if (PADDR[1:0] == 2'b00 && PADDR[11:2] < 10'd12) hit[PADDR[11:2]] = 1'b1;
  end
  assign PREADY  = acc;
  assign PSLVERR = acc & ~|hit;

  // ---------------- core ----------------
  logic [31:0]   c_enable;
  logic [31:0]   c_sw_set;
  logic          c_log_en;
  logic [31:0]   c_log_base;
  logic [15:0]   c_log_words;
  logic [31:0]   c_pending;
  logic [31:0]   c_claim;
  logic [15:0]   c_log_wp;
  logic          c_cpu_irq;
  logic          c_log_err;
  Interrupt_Controller_top #(.AXI_ID(AXI_ID)) u_core (
    .clk(PCLK),
    .rst_n(PRESETN),
    .irq_src(irq_src),
    .enable(c_enable),
    .sw_set(c_sw_set),
    .log_en(c_log_en),
    .log_base(c_log_base),
    .log_words(c_log_words),
    .pending(c_pending),
    .claim(c_claim),
    .log_wp(c_log_wp),
    .cpu_irq(c_cpu_irq),
    .log_err(c_log_err),
    .m_awid(m_awid),
    .m_awaddr(m_awaddr),
    .m_awlen(m_awlen),
    .m_awsize(m_awsize),
    .m_awburst(m_awburst),
    .m_awprot(m_awprot),
    .m_awvalid(m_awvalid),
    .m_awready(m_awready),
    .m_wdata(m_wdata),
    .m_wstrb(m_wstrb),
    .m_wlast(m_wlast),
    .m_wvalid(m_wvalid),
    .m_wready(m_wready),
    .m_bid(m_bid),
    .m_bresp(m_bresp),
    .m_bvalid(m_bvalid),
    .m_bready(m_bready),
    .m_arid(m_arid),
    .m_araddr(m_araddr),
    .m_arlen(m_arlen),
    .m_arsize(m_arsize),
    .m_arburst(m_arburst),
    .m_arprot(m_arprot),
    .m_arvalid(m_arvalid),
    .m_arready(m_arready),
    .m_rid(m_rid),
    .m_rdata(m_rdata),
    .m_rresp(m_rresp),
    .m_rlast(m_rlast),
    .m_rvalid(m_rvalid),
    .m_rready(m_rready)
  );
  assign cpu_irq = c_cpu_irq;  // also readable in the registers

  // ---------------- registers ----------------
  logic [1:0] irq_status, irq_enable, irq_set;
  logic [31:0] scratch;
  logic [31:0] r_ENABLE;   // 12'h014 ENABLE
  logic [31:0] r_SW_SET;   // 12'h018 SW_SET
  logic [16:0] r_LOG_CTRL;   // 12'h01C LOG_CTRL
  logic [31:0] r_LOG_BASE;   // 12'h020 LOG_BASE

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      irq_status <= '0; irq_enable <= '0; scratch <= '0;
      r_ENABLE <= 32'h0;
      r_SW_SET <= 32'h0;
      r_LOG_CTRL <= 17'h0;
      r_LOG_BASE <= 32'h0;
    end else begin
      irq_status <= (irq_status & ~((wr && hit[1]) ? PWDATA[1:0] & wmask[1:0] : '0)) | irq_set;
      if (wr && hit[2]) irq_enable <= (irq_enable & ~wmask[1:0]) | (PWDATA[1:0] & wmask[1:0]);
      if (wr && hit[4]) scratch <= (scratch & ~wmask) | (PWDATA & wmask);
      if (wr && hit[5]) r_ENABLE <= (r_ENABLE & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[6]) r_SW_SET <= (r_SW_SET & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[7]) r_LOG_CTRL <= (r_LOG_CTRL & ~wmask[16:0]) | (PWDATA[16:0] & wmask[16:0]);
      if (wr && hit[8]) r_LOG_BASE <= (r_LOG_BASE & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
    end
  end

  // ---------------- core inputs ----------------
  assign c_enable = r_ENABLE[31:0];
  assign c_sw_set = r_SW_SET[31:0];
  assign c_log_en = r_LOG_CTRL[0:0];
  assign c_log_words = r_LOG_CTRL[16:1];
  assign c_log_base = r_LOG_BASE[31:0];

  // ---------------- interrupts and flags ----------------
  always_comb begin
    irq_set = '0;
    irq_set[0] = c_cpu_irq;
    irq_set[1] = c_log_err;
  end
  assign irq = |(irq_status & irq_enable);

  // ---------------- read mux ----------------
  logic [31:0] apb_rdata;
  always_comb begin
    apb_rdata = '0;
    case (PADDR[11:2])
      10'd0: apb_rdata = ID_VALUE;
      10'd1: apb_rdata = 32'(irq_status);
      10'd2: apb_rdata = 32'(irq_enable);
      10'd4: apb_rdata = scratch;
      10'd5: apb_rdata = 32'(r_ENABLE);
      10'd6: apb_rdata = 32'(r_SW_SET);
      10'd7: apb_rdata = 32'(r_LOG_CTRL);
      10'd8: apb_rdata = 32'(r_LOG_BASE);
      10'd9: apb_rdata = 32'({c_pending});
      10'd10: apb_rdata = 32'({c_claim});
      10'd11: apb_rdata = 32'({c_cpu_irq, c_log_wp});
      default: apb_rdata = '0;
    endcase
  end
  assign PRDATA = (rd && |hit) ? apb_rdata : '0;
endmodule
